import time
import json

def main():
    daytona = Daytona()
    sandbox = daytona.create()
    print(f"Sandbox created with ID: {sandbox.id}")
    print(f"Sandbox state: {sandbox.state}")

    # Print all sandbox attributes
    print("\nSandbox attributes:")
    for attr in dir(sandbox):
        if not attr.startswith('_'):
            try:
                val = getattr(sandbox, attr)
                if not callable(val):
                    print(f"  {attr}: {val}")
            except:
                pass

    # Wait longer
    print("\nWaiting 30 seconds for sandbox to fully initialize...")
    time.sleep(30)

    print(f"Sandbox state after 30s: {sandbox.state}")

    # Try to execute
    try:
        response = sandbox.process.exec("echo 'Hello, World!'")
        print(f"Result: {response.result}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
